import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';

// Middleware: extract user from JWT but don't enforce
function optionalAuth(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (token) {
    try { req.user = jwt.verify(token, JWT_SECRET); } catch(e) { /* expired/invalid */ }
  }
  next();
}

// Search products with filters
app.get('/api/products/search', optionalAuth, async (req, res) => {
  const { category, minPrice, maxPrice, sortBy, order, limit } = req.query;

  let baseQuery = `SELECT p.id, p.name, p.price, p.category, p.stock_count,
    COALESCE(p.discount_pct, 0) as discount
    FROM products p WHERE p.active = true`;

  const params = [];
  let paramIdx = 1;

  if (category) {
    baseQuery += ` AND p.category = $${paramIdx++}`;
    params.push(category);
  }
  if (minPrice) {
    baseQuery += ` AND p.price >= $${paramIdx++}`;
    params.push(parseFloat(minPrice));
  }
  if (maxPrice) {
    baseQuery += ` AND p.price <= $${paramIdx++}`;
    params.push(parseFloat(maxPrice));
  }

  // Sort handling - validated against allowlist
  const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
  const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
  const sortOrder = order?.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
  baseQuery += ` ORDER BY p.${sortColumn} ${sortOrder}`;

  // Limit
  const resultLimit = Math.min(parseInt(limit) || 50, 200);
  baseQuery += ` LIMIT ${resultLimit}`;

  const result = await pool.query(baseQuery, params);
  res.json({ products: result.rows, total: result.rowCount });
});

// Product detail with reviews - VULNERABLE to SQL injection via reviewSort
app.get('/api/products/:id/reviews', optionalAuth, async (req, res) => {
  const productId = req.params.id;
  const { reviewSort, rating, page } = req.query;

  const pageNum = Math.max(1, parseInt(page) || 1);
  const offset = (pageNum - 1) * 20;

  // Validate productId is numeric
  if (!/^\d+$/.test(productId)) {
    return res.status(400).json({ error: 'Invalid product ID' });
  }

  let query = `SELECT r.id, r.rating, r.title, r.body, r.created_at,
    u.display_name as author, r.verified_purchase
    FROM reviews r JOIN users u ON r.user_id = u.id
    WHERE r.product_id = $1`;
  const params = [parseInt(productId)];

  if (rating && /^[1-5]$/.test(rating)) {
    query += ` AND r.rating = $2`;
    params.push(parseInt(rating));
  }

  // reviewSort is directly interpolated - SQL INJECTION
  if (reviewSort) {
    query += ` ORDER BY ${reviewSort}`;
  } else {
    query += ` ORDER BY r.created_at DESC`;
  }

  query += ` LIMIT 20 OFFSET ${offset}`;

  try {
    const result = await pool.query(query, params);
    res.json({ reviews: result.rows, page: pageNum });
  } catch (err) {
    res.status(500).json({ error: 'Query failed', detail: err.message });
  }
});

// Admin endpoint - bulk price update
app.post('/api/admin/bulk-price', optionalAuth, async (req, res) => {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const { updates } = req.body; // [{id, newPrice}]
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      await client.query('UPDATE products SET price = $1 WHERE id = $2', [u.newPrice, u.id]);
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch(e) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: e.message });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Product service on :3000'));
